-- Year-end employee service review: synthetic ATM dispute data.
-- SQLite 3.25+. All names/IDs/timestamps/ratings/notes are fictional.
-- EMP-01 is a fictional employee, not a real person's performance record.
-- Review period: 2025-01-01 through 2025-12-31; 10 received cases per month.
-- One issue type: pending/timeout, account debited, ATM did not dispense cash.
-- Five-workday SLA is the business premise, not a universal legal requirement.
-- Model hours: 08:00-17:00 continuous; no lunch break modeled.
-- Response target: 30 WORKING minutes, assumed for this exercise.
-- Mon-Fri excluding dates in work_calendar. See workbook Guide for sources/scope.
-- No automatic bonus score or amount: use metrics and reviewed evidence.
-- Run on a new empty SQLite database; no tables are dropped.
CREATE TABLE settings(sla_days INTEGER,response_target_min INTEGER,open_min INTEGER,close_min INTEGER);
CREATE TABLE work_calendar(calendar_date TEXT PRIMARY KEY,is_workday INTEGER,workday_index INTEGER);
CREATE TABLE cases(
 case_id TEXT PRIMARY KEY,employee_id TEXT NOT NULL,received_at TEXT NOT NULL,
 first_response_at TEXT NOT NULL,verified_at TEXT NOT NULL,refunded_at TEXT NOT NULL,
 amount_vnd INTEGER NOT NULL,rework_required INTEGER NOT NULL,csat_score INTEGER,
 feedback_theme TEXT NOT NULL,feedback_responsibility TEXT NOT NULL,feedback_note TEXT NOT NULL);

CREATE VIEW service_metrics AS
SELECT a.*,substr(a.received_at,1,7) AS received_month,
 (cd.workday_index-cc.workday_index)*(s.close_min-s.open_min)+(CAST(strftime('%H',a.first_response_at) AS INTEGER)*60+CAST(strftime('%M',a.first_response_at) AS INTEGER))-(CAST(strftime('%H',a.received_at) AS INTEGER)*60+CAST(strftime('%M',a.received_at) AS INTEGER)) AS response_work_minutes,
 CASE WHEN (cd.workday_index-cc.workday_index)*(s.close_min-s.open_min)+(CAST(strftime('%H',a.first_response_at) AS INTEGER)*60+CAST(strftime('%M',a.first_response_at) AS INTEGER))-(CAST(strftime('%H',a.received_at) AS INTEGER)*60+CAST(strftime('%M',a.received_at) AS INTEGER))<=s.response_target_min THEN 1 ELSE 0 END AS response_target_met,
 ce.workday_index-cc.workday_index AS verification_workdays,
 ROUND((julianday(a.refunded_at)-julianday(a.received_at))*24,2) AS customer_wait_hours,
 (cf.workday_index-ce.workday_index)*(s.close_min-s.open_min)+(CAST(strftime('%H',a.refunded_at) AS INTEGER)*60+CAST(strftime('%M',a.refunded_at) AS INTEGER))-(CAST(strftime('%H',a.verified_at) AS INTEGER)*60+CAST(strftime('%M',a.verified_at) AS INTEGER)) AS accounting_wait_work_minutes,
 CASE WHEN date(a.received_at)=date(a.refunded_at) THEN 1 ELSE 0 END AS same_day_refund,
 limitday.calendar_date || ' 17:00:00' AS sla_deadline,
 CASE WHEN a.refunded_at<=limitday.calendar_date || ' 17:00:00' THEN 1 ELSE 0 END AS within_sla,
 CASE WHEN a.csat_score IS NOT NULL AND a.csat_score<=2 THEN 1 ELSE 0 END AS low_rating
FROM cases a CROSS JOIN settings s
JOIN work_calendar cc ON cc.calendar_date=date(a.received_at)
JOIN work_calendar cd ON cd.calendar_date=date(a.first_response_at)
JOIN work_calendar ce ON ce.calendar_date=date(a.verified_at)
JOIN work_calendar cf ON cf.calendar_date=date(a.refunded_at)
JOIN work_calendar limitday ON limitday.is_workday=1 AND limitday.workday_index=cc.workday_index+s.sla_days;

-- Q1. Data quality and calendar coverage; violation counts must be zero.
SELECT COUNT(*) AS total_cases,COUNT(*)-COUNT(DISTINCT case_id) AS duplicates,
 SUM(CASE WHEN received_at>first_response_at OR first_response_at>verified_at OR verified_at>refunded_at THEN 1 ELSE 0 END) AS invalid_order,
 SUM(CASE WHEN csat_score IS NOT NULL AND csat_score NOT BETWEEN 1 AND 5 THEN 1 ELSE 0 END) AS invalid_csat
FROM cases;
SELECT (SELECT COUNT(*) FROM cases)-(SELECT COUNT(*) FROM service_metrics) AS calendar_join_loss;

-- Q2. Employee evidence for year-end review; CSAT denominator is survey responses.
SELECT employee_id,COUNT(*) AS total_cases,
 ROUND(AVG(response_work_minutes),2) AS avg_response_work_minutes,
 SUM(response_target_met) AS prompt_responses,ROUND(100.0*AVG(response_target_met),1) AS prompt_response_pct,
 SUM(within_sla) AS within_sla_cases,ROUND(100.0*AVG(within_sla),1) AS within_sla_pct,
 SUM(same_day_refund) AS same_day_refunds,SUM(rework_required) AS rework_cases,
 COUNT(csat_score) AS survey_responses,ROUND(100.0*COUNT(csat_score)/COUNT(*),1) AS survey_coverage_pct,
 ROUND(AVG(csat_score),2) AS avg_csat,
 SUM(low_rating) AS low_ratings,
 SUM(CASE WHEN low_rating=1 AND feedback_responsibility='Employee' THEN 1 ELSE 0 END) AS service_related_low_ratings
FROM service_metrics GROUP BY employee_id;

-- Q3. Monthly review: count and rate stay separate; do not average monthly rates.
SELECT received_month,COUNT(*) AS cases,ROUND(AVG(response_work_minutes),2) AS avg_response_min,
 ROUND(100.0*AVG(response_target_met),1) AS prompt_pct,SUM(within_sla) AS within_sla,
 SUM(rework_required) AS rework_cases,COUNT(csat_score) AS survey_responses,
 ROUND(AVG(csat_score),2) AS avg_csat,SUM(low_rating) AS low_ratings
FROM service_metrics GROUP BY received_month ORDER BY received_month;

-- Q4. Feedback context; category is an illustrative reviewed attribution, not inferred from rating.
SELECT feedback_responsibility,COUNT(*) AS low_ratings
FROM service_metrics WHERE low_rating=1 GROUP BY feedback_responsibility;

-- Q5. Evidence requiring review before a reward decision.
SELECT case_id,received_at,response_work_minutes,rework_required,csat_score,
 feedback_theme,feedback_responsibility,feedback_note
FROM service_metrics
WHERE response_target_met=0 OR rework_required=1 OR low_rating=1
ORDER BY received_at;

-- Q6. Separate employee verification from accounting-posting wait.
SELECT ROUND(AVG(verification_workdays),2) AS avg_verification_workdays,
 ROUND(AVG(accounting_wait_work_minutes),2) AS avg_accounting_wait_work_minutes,
 ROUND(AVG(customer_wait_hours),2) AS avg_customer_wait_clock_hours
FROM service_metrics;

-- Q7. Each month's longest initial wait (working minutes).
WITH ranked AS(
 SELECT case_id,received_month,response_work_minutes,
 ROW_NUMBER() OVER(PARTITION BY received_month ORDER BY response_work_minutes DESC,case_id) AS rn
 FROM service_metrics
) SELECT case_id,received_month,response_work_minutes FROM ranked WHERE rn=1;

-- Q8. Refund SLA exceptions. Empty in this scenario; does NOT imply every service dimension is perfect.
SELECT case_id,employee_id,received_at,refunded_at,sla_deadline FROM service_metrics WHERE within_sla=0;
